    <?php if($groups): ?><?php foreach($groups as$group): ?><fieldset class="audience-group-choices"><legend><?= $h($group['name']) ?><?= $group['display_type']==='hidden'?' (internal)':'' ?></legend><?php if($group['display_type']==='dropdown'): ?><select name="group_pick[<?= (int)$group['id'] ?>]" aria-label="<?= $h($group['name']) ?>"><option value="">None</option><?php foreach($group['options']as$option): ?><option value="<?= (int)$option['id'] ?>"<?= in_array((int)$option['id'],array_map('intval',$contact['group_ids']),true)?' selected':'' ?>><?= $h($option['name']) ?></option><?php endforeach; ?></select><?php else: ?><?php if($group['display_type']==='radio'): ?><label class="audience-check"><input type="radio" name="group_pick[<?= (int)$group['id'] ?>]" value="" checked>None</label><?php endif; ?><?php foreach($group['options']as$option): ?><label class="audience-check"><input type="<?= $group['display_type']==='radio'?'radio':'checkbox' ?>" name="<?= $group['display_type']==='radio'?'group_pick['.(int)$group['id'].']':'group_ids[]' ?>" value="<?= (int)$option['id'] ?>"<?= in_array((int)$option['id'],array_map('intval',$contact['group_ids']),true)?' checked':'' ?>><?= $h($option['name']) ?></label><?php endforeach; ?><?php endif; ?></fieldset><?php endforeach; ?><?php endif; ?>
